  /// other line passes through verbatim (no inner conversion).
  void _insideCode(String line) {
    if (line.trim() == '{code}') {
      _out.add('```');
      _inCode = false;
    } else {
      _out.add(line);
    }
  }

  /// Inside a panel: body lines become blockquotes; `{panel}` closes it.
  void _insidePanel(String line) {
    if (line.trim() == '{panel}') {
      _inPanel = false;
    } else {
      _out.add('> ${_convertLine(line)}');
    }
  }

