      cliPrompt,
      merged,
      workingDirectory,
    );
    if (combined == null || combined.trim().isEmpty) return cliCommands;
    return _appendPromptToCommands(cliCommands, combined);
  }

  /// Combines [cliPrompt] and [cliPrompts] into a single prompt string.
  ///
