  ///
  /// Mirrors `InstructionProcessor.buildCombinedPrompt()`.
  String? _buildCombinedPrompt(
    String? cliPrompt,
    List<String>? cliPrompts,
    String? workingDirectory,
  ) {
    final parts = <String>[];
